function replaceMain(html, body) {
  const re = /<main id="main-content" tabindex="-1">[\s\S]*?<\/main>/i;
  if (!re.test(html)) throw new Error('Splendoria legal main anchor not found');
  return html.replace(re, `<main id="main-content" tabindex="-1">${body}</main>`);
}

function pageLinks(locale) {
  return {
    '/': `/${locale}/`,
    '/#metodo': `/${locale}/#metodo`,
    '/#formule': `/${locale}/#formule`,
    '/#contatti': `/${locale}/#contatti`,
    '/guida': locale === 'de' ? '/de/leitfaden' : '/en/guide',
    '/privacy-policy': LEGAL_PATHS.privacy[locale],
    '/cookie-policy': LEGAL_PATHS.cookies[locale],
    '/termini-condizioni': LEGAL_PATHS.terms[locale],
    '/note-legali': LEGAL_PATHS.notice[locale],
    '/trasparenza-ai': LEGAL_PATHS.ai[locale]
  };
}

export const LEGAL_PAGES = Object.entries(LEGAL_PATHS).map(([key, paths]) => ({
  key,
  basePath: paths.it,
  paths,
  localize(html, locale) {
    let localized = replaceMain(html, BODIES[key][locale]);
    localized = applyTextMap(localized, CHROME[locale]);
    localized = applyAttributeMap(localized, ATTRS[locale]);
    localized = localizePublicSeo(localized, locale, META[key][locale], paths);
    localized = rewriteExactHrefs(localized, pageLinks(locale));
    return localized;
  }
}));
